WITH seed(text_key,body,variables) AS (VALUES
 ('chat.report.conversation','Report conversation','[]'),
 ('chat.report.message','Report message {number}','["number"]'),
 ('chat.report.ended','Ended chats','[]'),
 ('chat.report.ended_empty','No ended chats are currently eligible for reporting.','[]'))
INSERT INTO catalog.ui_texts(id,locale_code,text_key,value,category,variables,is_active,created_at,updated_at)
SELECT md5('en:'||text_key)::uuid,'en',text_key,body,'message',variables::jsonb,true,clock_timestamp(),clock_timestamp() FROM seed;

-- Code-owned minimal transport rules. Classification grants no evidence access
-- or purge authority. Unknown shapes and private content remain unclassified.
